from typing import Optional

from pyvkteamsclient.staffd.base.client import BaseStaffDClient


class GroupsMethods(BaseStaffDClient):
    def add_group(self, group_id: str, name: str, parent_id: Optional[str] = None):
        json_data = {"id": group_id, "name": name}

        if parent_id is not None:
            json_data["parentID"] = parent_id

        return self.post(path="groups", json=json_data)

    def get_group_by_id(self, group_id: int | str):
        return self.get(path=f"groups/{group_id}")

    def get_groups_list(self, _from: int = 0, _max: int = 1000):
        return self.get(path="groups/list", **{"from": _from, "max": _max})

    def get_group_users(self, group_id: int | str):
        return self.get(path=f"groups/{group_id}/users")

    def remove_group(self, group_id: int | str):
        return self.delete(path=f"groups/{group_id}")
